  { json: { url: 'https://www.wired.com/feed/rss', name: 'WIRED' } }
];

// поддержка RSS (item) и Atom (entry) форматов
function getTag(tag, text) {
  // Строковая конкатенация вместо template literal — избегаем проблем с escape в JSON
  var regex = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  var match = text.match(regex);
  if (!match) return '';
  return match[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').trim();
}

function getLink(text) {
  // Atom: <link href="..." />
  var atomHref = text.match(/<link[^>]+href=["']([^"']+)["'][^>]*\/?>/);
  if (atomHref) return atomHref[1].trim();
  // RSS: <link>url</link>
  return getTag('link', text);
}

var result = [];
for (var item of $input.all()) {
  var xml = item.json.data || '';
  if (!xml) continue;
  var src = item.json.name || 'News';

  var isAtom = xml.includes('<entry>');
  var openTag = isAtom ? '<entry>' : '<item>';
  var closeTag = isAtom ? '</entry>' : '</item>';
  var dateTag = isAtom ? 'updated' : 'pubDate';

  var parts = xml.split(openTag);
  for (var i = 1; i < parts.length && i <= 5; i++) {
    var b = parts[i].split(closeTag)[0];
    var title = getTag('title', b);
    var url = getLink(b);
    var content = getTag('description', b).replace(/<[^>]+>/g, '').trim()
      || getTag('summary', b).replace(/<[^>]+>/g, '').trim();
    var date = getTag(dateTag, b);

    if (title && url) {
      result.push({ json: { source: src, title: title, url: url, content: content, date: date } });
    }
  }
}
return result;

// Читаем базу и очищаем ссылки
const db = $('Чтение Базы').all()
  .map(i => (i.json.url || '').trim().replace(/\/$/, ''))
  .filter(url => url !== '');

const news = $input.all();
const cutoff = new Date();
cutoff.setHours(cutoff.getHours() - 24);

const filtered = news.filter(n => {
  if (!n.json.url) return false;
  if (!n.json.title || n.json.title.trim() === '') return false;

  const currentUrl = n.json.url.trim().replace(/\/$/, '');
  const isNew = !db.includes(currentUrl);

  if (!n.json.date) return false;
  const isFresh = new Date(n.json.date) > cutoff;

  return isNew && isFresh;
});

// Берем 10 штук для ИИ
return filtered.slice(0, 10);

// Берем полные данные из фильтра, игнорируя обрезанные данные от базы
const items = $('Фильтр Дубликатов').all(); 
if (items.length === 0) return [];

const newsList = items.map((n, i) => ({
  id: i,
  title: n.json.title || "",
  text: (n.json.content || "").substring(0, 600)
}));

const promptText = `You are a professional translator. 
Task: Translate news from English to Russian.

RULES:
1. Translate "title" -> "ru_title".
2. Translate "text" -> "ru_text".
3. Summary (1 sentence) -> "sum".
4. Output ONLY a valid JSON array.

INPUT:
${JSON.stringify(newsList)}`;

return [{
  json: {
    model: 'gemma-4-e4b',
    messages: [
      { role: 'system', content: 'You strictly output JSON arrays and translate everything to Russian.' },
      { role: 'user', content: promptText }
    ],
    temperature: 0.1,
    max_tokens: 8192
  }
}];

let aiData = [];
try {
  const aiRaw = $input.first().json?.choices?.[0]?.message?.content || '';
  const jsonMatch = aiRaw.match(/\[[\s\S]*\]/);
  if (jsonMatch) aiData = JSON.parse(jsonMatch[0]);
} catch(e) {
  console.error('Ошибка парсинга:', e.message);
}

const originals = $('Фильтр Дубликатов').all();

return originals.map((origItem, i) => {
  const orig = origItem.json;
  const ai = aiData.find(item => item.id === i) || {};

  // Берем русский перевод, если он есть и не пустой. Иначе — оригинал.
  const finalTitle = (ai.ru_title && String(ai.ru_title).trim() !== '') ? ai.ru_title : orig.title;
  const finalContent = (ai.ru_text && String(ai.ru_text).trim() !== '') ? ai.ru_text : orig.content;

  return {
    json: {
      title: finalTitle,
      summary: ai.sum || '', // Выжимка от ИИ
      content: (finalContent || '').substring(0, 800),
      url: orig.url,
      source: orig.source
    }
  };
});

